// LGS · Türkçe (8. sınıf) — orta (2) ve zor (3) düzey. «…» işaretli sözcükler, kitapçıktaki altı çizili sözcüklerin yerini tutar.
LGS_ADD("tr", [
 // ---------- Fiilimsiler ----------
 ["t1","Aşağıdaki cümlelerin hangisinde isim-fiil kullanılmıştır?",["Koşarak gelen çocuk nefes nefese kalmıştı.","Kitap okumayı her şeyden çok severdi.","Akşam olunca bahçeye çıktık.","Yazılacak çok şey vardı."],1,"“Okuma” (-ma) isim-fiildir. Koşarak ve olunca zarf-fiil; gelen ve yazılacak sıfat-fiildir.",2],
 ["t1","Aşağıdaki cümlelerin hangisinde fiilimsi yoktur?",["Annem bize dondurma aldı.","Gülerek yanımıza geldi.","Okunacak kitapları masaya koydum.","Yağmur yağınca sokaklar boşaldı."],0,"“Dondurma” kalıcı isim olmuştur, fiilimsi sayılmaz. Diğerlerinde gülerek, okunacak, yağınca fiilimsidir.",2],
 ["t1","Aşağıdaki cümlelerin hangisinde «…» ile gösterilen sözcük sıfat-fiildir?",["Sabah «erkenden» yola çıktık.","«Bitmez» tükenmez bir enerjisi vardı.","Bu dersi «anlayınca» rahatladım.","Her akşam «yürümek» ona iyi geliyor."],1,"“Bitmez” (-maz) sıfat-fiildir ve “enerji” ismini nitelemektedir. Anlayınca zarf-fiil, yürümek isim-fiildir; erkenden fiilimsi değildir.",2],
 ["t1","“Benim en büyük zevkim, akşamları sahilde yürümektir.” cümlesindeki fiilimsiyle ilgili hangisi doğrudur?",["Zarf-fiildir ve zaman bildirir.","İsim-fiildir ve cümlenin yükleminde yer alır.","Sıfat-fiildir ve özneyi niteler.","Kalıcı isim olmuştur."],1,"“Yürümektir” isim-fiil (-mak) almış ve cümlenin yüklemi olmuştur.",3],
 ["t1","“Okudukça yeni dünyalar keşfediyor, keşfettikçe daha çok okumak istiyordu.” cümlesindeki fiilimsiler hangi seçenekte doğru sınıflandırılmıştır?",["İki zarf-fiil, bir isim-fiil","İki sıfat-fiil, bir zarf-fiil","Üç zarf-fiil","Bir zarf-fiil, iki isim-fiil"],0,"Okudukça ve keşfettikçe (-dıkça) zarf-fiil, okumak (-mak) isim-fiildir.",3],
 ["t1","Aşağıdaki cümlelerin hangisinde zarf-fiil cümleye “durum” anlamı katmıştır?",["Sen gelince yola çıkarız.","Sınav bitince herkes dışarı çıktı.","Çocuk ağlayarak annesine koştu.","Güneş batalı epey olmuştu."],2,"“Ağlayarak”, koşma eyleminin nasıl yapıldığını (durum) bildirir. Gelince, bitince ve batalı zaman anlamı katar.",3],
 ["t1","Aşağıdaki cümlelerin hangisinde adlaşmış sıfat-fiil, cümlenin öznesi olmuştur?",["Gelenler salona alındı.","Gelen misafirleri kapıda karşıladık.","Okumayı çok severim.","Eve dönünce uyudum."],0,"“Gelenler” sıfat-fiilin nitelediği isim düşmüş ve adlaşmıştır; cümlede özne görevindedir.",3],
 ["t1","Aşağıdaki cümlelerin hangisinde kalıcı isim olmuş bir sözcük vardır?",["Çakmağı masanın üzerinde unutmuşum.","Yazmak istediği her şeyi deftere geçirdi.","Koşan atlar tozu dumana kattı.","Çalışırken kimseyi duymuyordu."],0,"“Çakmak” bir nesnenin adı olmuştur, fiilimsi değildir. Yazmak, koşan ve çalışırken fiilimsidir.",2],
 ["t1","“Uzun süre çalışmadan başarılı olmak mümkün değildir.” cümlesinde kaç fiilimsi vardır?",["1","2","3","4"],1,"“Çalışmadan” zarf-fiil, “olmak” isim-fiildir. Toplam iki fiilimsi vardır.",3],
 ["t1","Aşağıdakilerin hangisinde «…» ile gösterilen fiilimsi, türü bakımından diğerlerinden farklıdır?",["Eve «girer girmez» telefonu açtı.","Kapıyı «çalmadan» içeri girdi.","Ders «bitince» bahçeye koştuk.","«Okunacak» kitapları bir kenara ayırdım."],3,"Girer girmez, çalmadan ve bitince zarf-fiildir; “okunacak” (-ecek) ise “kitaplar” ismini niteleyen sıfat-fiildir.",2],
 ["t1","Aşağıdaki cümlelerin hangisinde sıfat-fiil, “-ası” ekiyle yapılmıştır?",["Gülesi geldi ama kendini tuttu.","Gidilecek yol uzundu.","Kurumuş yapraklar yere dökülmüştü.","Bilinmeyen bir sebeple ertelendi."],0,"“Gülesi” (-ası) sıfat-fiildir; gidilecek -ecek, kurumuş -mış, bilinmeyen -an ekiyle yapılmıştır.",2],

 // ---------- Cümlenin Ögeleri ----------
 ["t2","“Dün akşam babam bize çok güzel bir hikâye anlattı.” cümlesinin ögeleri sırasıyla hangi seçenekte doğru verilmiştir?",["Zarf tümleci – Özne – Dolaylı tümleç – Belirtisiz nesne – Yüklem","Özne – Zarf tümleci – Nesne – Dolaylı tümleç – Yüklem","Zarf tümleci – Özne – Nesne – Belirtili nesne – Yüklem","Dolaylı tümleç – Özne – Zarf tümleci – Nesne – Yüklem"],0,"Dün akşam (ne zaman: zarf), babam (kim: özne), bize (kime: dolaylı), çok güzel bir hikâye (ne: belirtisiz nesne), anlattı (yüklem).",2],
 ["t2","Aşağıdaki cümlelerin hangisinde belirtili nesne kullanılmıştır?",["Akşam yemekten sonra kitap okudum.","Kardeşim bahçeden çiçek topladı.","Okuduğum romanı arkadaşıma verdim.","Annem pazardan sebze aldı."],2,"“Okuduğum romanı” -ı hâl ekini almış belirtili nesnedir. Diğerleri belirtisiz nesnedir.",2],
 ["t2","Aşağıdaki cümlelerin hangisinde nesne yoktur?",["Çocuklar akşama kadar parkta oynadı.","Öğretmen soruları tahtaya yazdı.","Sabah erkenden ekmek aldım.","Ödevini zamanında teslim etti."],0,"“Oynamak” bu cümlede nesne almamıştır. Diğerlerinde soruları, ekmek, ödevini nesnedir.",2],
 ["t2","“Akşama eve döneceğiz.” cümlesinde «akşama» ve «eve» sözcükleri hangi ögelerdir?",["İkisi de dolaylı tümleç","Akşama: zarf tümleci – Eve: dolaylı tümleç","Akşama: dolaylı tümleç – Eve: zarf tümleci","İkisi de zarf tümleci"],1,"“Akşama” -e hâl ekini almasına rağmen zaman bildirir, zarf tümlecidir. “Eve” yer bildirir, dolaylı tümleçtir.",3],
 ["t2","“Duvarlar dün akşam yeniden boyandı.” cümlesinin öznesiyle ilgili hangisi doğrudur?",["Gizli öznedir.","Sözde öznedir; işi yapan belli değildir.","Gerçek öznedir.","Cümlenin öznesi yoktur."],1,"Yüklem edilgen çatılıdır; “duvarlar” işi yapan değil, işten etkilenendir. Bu tür öznelere sözde özne denir.",3],
 ["t2","“En büyük hayalim, bir gün pilot olmaktır.” cümlesinin yüklemi ve öznesi hangi seçenekte doğru verilmiştir?",["Yüklem: olmaktır – Özne: pilot","Yüklem: pilot olmaktır – Özne: en büyük hayalim","Yüklem: hayalim – Özne: pilot","Yüklem: bir gün pilot olmaktır – Özne: en büyük"],1,"İsim cümlesinde yüklem “pilot olmaktır”dır; “bir gün” zaman bildirdiği için zarf tümlecidir. “Ne pilot olmaktır?” sorusunun cevabı öznedir.",3],
 ["t2","“Ahmet, sınıfın en çalışkan öğrencisi, bu yıl yine birinci oldu.” cümlesindeki ara söz hangi ögeyi açıklamaktadır?",["Yüklemi","Nesneyi","Özneyi","Zarf tümlecini"],2,"Virgüller arasındaki “sınıfın en çalışkan öğrencisi” ifadesi özne olan “Ahmet”i açıklar; ara sözler ayrı bir öge sayılmaz.",2],
 ["t2","“Sabah erkenden yola çıktık.” cümlesiyle ilgili hangisi doğrudur?",["Özne “sabah”tır.","Özne gizlidir (biz) ve cümlede nesne yoktur.","“Yola” nesnedir.","Cümlede zarf tümleci yoktur."],1,"Yüklemdeki kişi eki özneyi (biz) gösterir. “Sabah erkenden” zarf tümleci, “yola” dolaylı tümleçtir.",2],
 ["t2","Aşağıdaki cümlelerin hangisinde dolaylı tümleç yoktur?",["Bu konuda seninle aynı fikirdeyim.","Kitabı rafa yerleştirdi.","Yarın sabah erkenden kalkacağız.","Okuldan eve yürüyerek döndük."],2,"“Yarın sabah erkenden” zarf tümlecidir; cümlede yer bildiren bir öge yoktur. Diğerlerinde “bu konuda”, “rafa”, “okuldan / eve” dolaylı tümleçtir.",3],
 ["t2","“Yorgunluktan bitap düşen dedem, bahçedeki ağacın gölgesinde uzun süre dinlendi.” cümlesinde hangi öge yoktur?",["Özne","Nesne","Dolaylı tümleç","Zarf tümleci"],1,"Özne: yorgunluktan bitap düşen dedem; dolaylı: bahçedeki ağacın gölgesinde; zarf: uzun süre; yüklem: dinlendi. Nesne yoktur.",3],
 ["t2","Aşağıdaki cümlelerin hangisinde yüklem isim soylu bir sözcüktür (isim cümlesi)?",["Bu yolun sonu hiç de yakın değil.","Yarın şehre gideceğiz.","Kuşlar sabahları erkenden öter.","Bütün gece kitap okudu."],0,"“Yakın değil” isim soylu yüklemdir; diğerleri çekimli fiille kurulmuş fiil cümleleridir.",2],

 // ---------- Fiilde Çatı ----------
 ["t3","Aşağıdaki cümlelerin hangisinin yüklemi edilgen çatılıdır?",["Bütün kapılar dün gece kilitlendi.","Çocuklar bahçede koşuştu.","Ali aynanın karşısında tarandı.","Arkadaşlar bayramda bayramlaştı."],0,"“Kilitlendi” fiilinde işi yapan belli değildir; edilgendir. Koşuştu ve bayramlaştı işteş, tarandı dönüşlüdür.",2],
 ["t3","Aşağıdaki cümlelerin hangisinde yüklem geçişsizdir?",["Annem kurabiye yaptı.","Kuşlar sabaha karşı göğe doğru uçtu.","Bütün sınav sorularını çözdük.","Kardeşim odasını topladı."],1,"“Uçmak” nesne almayan, geçişsiz bir fiildir. Diğerleri nesne almıştır.",2],
 ["t3","Aşağıdaki cümlelerin hangisinde yüklem dönüşlü çatılıdır?",["Ağaçlar sonbaharda budandı.","Sabah erkenden kalkıp giyindim.","Eski binalar yıkıldı.","Bütün öğrenciler sınıfa alındı."],1,"“Giyinmek”, öznenin yaptığı işten kendisinin etkilendiğini gösterir; dönüşlüdür. Diğerleri edilgendir.",2],
 ["t3","Aşağıdaki cümlelerin hangisinde yüklem işteş çatılıdır?",["Çocuklar parkta saklambaç oynadı.","Kuşlar ağaçta ötüşüyordu.","Kapı sertçe kapandı.","Annem çamaşırları yıkadı."],1,"“Ötüşmek” birlikte yapılan bir eylemi anlatır (-ş eki); işteştir.",2],
 ["t3","“Annem bana odamı temizletti.” cümlesinin yüklemiyle ilgili hangisi doğrudur?",["Edilgen ve geçişsizdir.","Etken ve geçişlidir; ettirgen bir fiildir.","Dönüşlü ve geçişsizdir.","İşteş ve geçişlidir."],1,"Özne (annem) bellidir: etken. “Odamı” nesnedir: geçişli. İşi başkasına yaptırma anlamı vardır: ettirgen.",3],
 ["t3","Aşağıdaki cümlelerin hangisinin yüklemi hem etken hem geçişsizdir?",["Mektup postaya verildi.","Bebek bütün gece uyudu.","Kitapları kütüphaneye götürdük.","Masa yeniden boyandı."],1,"“Uyudu” fiilinin öznesi bellidir (etken) ve nesne almaz (geçişsiz).",3],
 ["t3","Edilgen çatılı fiillerle ilgili hangisi doğrudur?",["Gerçek özneleri her zaman cümlede bulunur.","Nesne almazlar; bu yüzden geçişsiz sayılırlar.","Sadece -ş ekiyle yapılırlar.","İşi yapanın kendisi olduğunu bildirirler."],1,"Edilgen fiillerde nesne, sözde özne olur; bu nedenle edilgen fiiller nesne almaz ve geçişsiz kabul edilir.",3],
 ["t3","Aşağıdaki cümlelerin hangisinde yüklem diğerlerinden farklı bir çatı özelliği taşır?",["Yollar karla kapandı.","Sorular dikkatle hazırlandı.","Eserler müzeye taşındı.","Çocuk annesini görünce sevindi."],3,"“Sevindi” etkendir; diğerleri edilgendir (işi yapan belli değil).",3],
 ["t3","“Komşularla bayramda tatlı tatlı söyleştik.” cümlesinin yüklemi hangi çatı özelliklerini taşır?",["Edilgen – geçişli","İşteş – geçişsiz","Dönüşlü – geçişli","Etken – geçişli"],1,"“Söyleşmek” karşılıklı yapılan bir eylemdir (işteş); cümlede nesne yoktur (geçişsiz).",3],

 // ---------- Cümle Türleri ----------
 ["t4","Aşağıdakilerden hangisi yapısına göre basit bir cümledir?",["Yarın sabah erkenden yola çıkacağız.","Eve gelince bana haber ver.","Hava soğuktu ama dışarı çıktık.","Kapıyı açtı, içeri girdi."],0,"Tek yüklemi olan ve fiilimsi içermeyen cümle basit cümledir. Gelince fiilimsi içerir (birleşik), diğerleri bağlı ve sıralıdır.",2],
 ["t4","Aşağıdaki cümlelerin hangisi yapıca olumsuz, anlamca olumludur?",["Bu filmi izlemedim.","Onu sevmeyen yoktur.","Yarın okula gitmeyeceğim.","Kimse bu soruyu çözemedi."],1,"“Onu sevmeyen yoktur” cümlesi biçimce olumsuz olsa da “herkes onu sever” anlamı taşır.",3],
 ["t4","Aşağıdaki cümlelerin hangisi şartlı birleşik cümledir?",["Erken kalkarsan otobüse yetişirsin.","Duydum ki bizi unutmuşsun.","Kitap okumayı çok severim.","Hem çalıştı hem kazandı."],0,"“Kalkarsan” şart (-se) anlamı taşıyan yan cümledir.",2],
 ["t4","“Bu kadar güzel bir manzarayı kim sevmez?” cümlesiyle ilgili hangisi doğrudur?",["Gerçek bir soru sorulmaktadır ve cevap beklenir.","Soru biçimindedir; ancak “herkes sever” yargısı taşır.","Ünlem cümlesidir.","Olumsuz bir yargı bildirir."],1,"Biçimce soru olan cümle cevap beklemez; anlamca olumlu bir yargı taşır.",3],
 ["t4","Aşağıdakilerden hangisi devrik bir cümledir?",["Sonunda beklenen gün geldi.","Geldi sonunda beklenen gün.","Beklenen gün sonunda geldi.","Beklediğimiz gün nihayet geldi."],1,"Yüklemi sonda olmayan cümleler devriktir. B seçeneğinde yüklem (geldi) başa alınmıştır.",2],
 ["t4","Aşağıdaki cümlelerin hangisi yüklemine göre isim cümlesi, yapısına göre birleşik bir cümledir?",["Okuduğum kitap çok sürükleyiciydi.","Bu yolun sonu çok uzak.","Akşam olunca eve döndük.","Kardeşim çok yorgundu ama uyumadı."],0,"Yüklem “sürükleyiciydi” isim soyludur ve cümlede “okuduğum” fiilimsisi vardır: birleşik isim cümlesi.",3],
 ["t4","Aşağıdaki cümlelerden hangisi sıralı cümledir?",["Okula gidip derse girdim.","Kapıyı açtı, ışığı yaktı, içeri girdi.","Hava çok soğuktu ama dışarı çıktık.","Bu kitabı okuyan herkes beğenir."],1,"Virgülle ayrılmış ve kendi başına yüklemi olan cümleler sıralı cümle oluşturur. A'da “gidip” fiilimsi olduğu için cümle birleşiktir.",3],
 ["t4","Aşağıdaki cümlelerden hangisi bağlı cümledir?",["Çok çalıştı fakat istediği sonucu alamadı.","Yağmur yağınca sokaklar boşaldı.","Bütün gün evde kitap okudu.","Geldi, gördü, yendi."],0,"İki ayrı yargı “fakat” bağlacıyla birbirine bağlanmıştır.",2],

 // ---------- Yazım Kuralları ve Noktalama ----------
 ["t5","Aşağıdaki cümlelerin hangisinde yazım yanlışı vardır?",["Her şey yolunda gidiyordu.","Bu konuda hiçbir fikrim yok.","Birkaç gün sonra döneceğiz.","Herkez toplantıya zamanında geldi."],3,"Doğrusu “herkes”tir. Her şey ayrı, hiçbir ve birkaç bitişik yazılır.",2],
 ["t5","Aşağıdaki cümlelerin hangisinde “de” bağlacının yazımı yanlıştır?",["Sen de bizimle gel.","Kitabı masada bıraktım.","Ben de bu filmi izledim.","Okuldada arkadaşlarımla oynadım."],3,"Bağlaç olan “de” ayrı yazılır: “Okulda da”. “Masada” bulunma hâl ekidir, bitişik yazılır.",2],
 ["t5","Aşağıdaki cümlelerin hangisinde “ki”nin yazımı yanlıştır?",["Duydum ki yarın tatil olacakmış.","Evdeki eski kitapları kütüphaneye bağışladık.","Seninki benimkinden daha güzel olmuş.","Öyleki herkes şaşkınlıktan donup kaldı."],3,"Bağlaç olan “ki” ayrı yazılır: “öyle ki”. Evdeki (sıfat yapan -ki) ve seninki (ilgi zamiri) bitişiktir.",3],
 ["t5","Aşağıdaki cümlelerin hangisinde kesme işaretinin kullanımı yanlıştır?",["Atatürk 19 Mayıs 1919'da Samsun'a çıktı.","TBMM'nin açılışı 23 Nisan 1920'dedir.","Bu yıl Türk Dil Kurumu'na yeni bir başkan seçildi.","Ankara'nın havası bugün çok güzeldi."],2,"Kurum ve kuruluş adlarına getirilen ekler kesme işaretiyle ayrılmaz: “Türk Dil Kurumuna”. Kısaltmalara (TBMM'nin) gelen ekler ise ayrılır.",3],
 ["t5","Aşağıdaki cümlelerin hangisinde büyük harflerin kullanımı yanlıştır?",["Her yıl Mayıs ayında yaylaya çıkarız.","Atatürk 10 Kasım 1938'de hayatını kaybetti.","Doğu Anadolu'da kışlar çok sert geçer.","Bugün Kuzey Kutbu ile ilgili bir belgesel izledik."],0,"Belirli bir tarih bildirmeyen ay adları küçük harfle yazılır: “her yıl mayıs ayında”. Belirli tarihlerdeki ay ve gün adları büyük harfle başlar.",3],
 ["t5","Aşağıdaki cümlelerin hangisinde sayının yazımı yanlıştır?",["Yarışmada 3'üncü oldu.","Kitabın 245. sayfasını okuyordum.","On beş gün sonra döneceğiz.","Bu okulda üçyüz öğrenci var."],3,"Sayılar ayrı yazılır: “üç yüz”. Sıra sayıları rakamla “3'üncü” ya da “3.” biçiminde yazılır.",2],
 ["t5","Aşağıdaki cümlelerin hangisinde “mi” soru ekinin yazımı yanlıştır?",["Yarın sen de gelecek misin?","Bu kitabı okudun mu?","Ödevlerini bitirdinmi?","Hava güzel mi bugün?"],2,"Soru eki “mi” her zaman ayrı yazılır: “bitirdin mi”.",2],
 ["t5","“Çantama defterlerimi ( ) kalemlerimi ( ) kitaplarımı koydum ( ) yola çıktım ( )” cümlesinde boş bırakılan yerlere sırasıyla hangi noktalama işaretleri getirilmelidir?",["(,) (,) (,) (.)","(;) (,) (.) (.)","(,) (ve) (:) (!)","(:) (,) (,) (.)"],0,"Eş görevli sözcükler ve sıralı cümleler virgülle ayrılır; cümle sonuna nokta konur.",2],
 ["t5","Aşağıdaki cümlelerin hangisinde iki nokta (:) yanlış kullanılmıştır?",["Atatürk şöyle diyor: “Hayatta en hakiki mürşit ilimdir.”","Pazardan şunları aldık: domates, biber, patlıcan.","Yarın: sabah erkenden yola çıkacağız.","Başarının sırrı şudur: düzenli çalışmak."],2,"İki nokta, açıklama, örnek ve alıntıdan önce kullanılır. “Yarın” sözcüğünden sonra açıklama gelmediği için kullanım yanlıştır.",3],
 ["t5","Aşağıdaki cümlelerin hangisinde noktalı virgül (;) doğru kullanılmıştır?",["Bu sabah; çok erken uyandım.","Kardeşim çok yorgundu; bu yüzden erkenden uyudu.","Kitap; kalem ve defter aldım.","Yarın; okula gidiyorum."],1,"Noktalı virgül, bağlaçla bağlanan ve anlamca ilişkili cümleleri ayırmak için kullanılabilir.",3],
 ["t5","Aşağıdaki cümlelerin hangisinde birleşik bir sözcüğün yazımı yanlıştır?",["Bahçede hanımeli kokuları vardı.","Ayakkabılarını kapının önünde çıkardı.","Kardeşim Kızılay'a kan bağışladı.","Yağmurdan sonra gök kuşağı çıktı."],3,"Türk Dil Kurumunun yazım kılavuzuna göre “gökkuşağı” bitişik yazılır.",3],

 // ---------- Sözcükte ve Cümlede Anlam ----------
 ["t6","Aşağıdaki cümlelerin hangisinde «…» ile gösterilen sözcük mecaz anlamda kullanılmıştır?",["Bu çorba çok «sıcak», biraz bekle.","Arkadaşının «soğuk» davranışları onu üzdü.","Kışın denizin suyu çok «soğuk» olur.","Fırından yeni çıkan «sıcak» ekmekleri aldık."],1,"“Soğuk davranış” ilgisiz, sevimsiz anlamında mecazdır. Diğerlerinde sözcükler gerçek anlamdadır.",2],
 ["t6","Aşağıdaki cümlelerin hangisinde terim anlamlı bir sözcük kullanılmıştır?",["Ayağına diken battı.","Bu üçgenin açılarını hesapla.","Kalbini kırmak istemedim.","Yüzü güldü."],1,"“Açı” matematik alanına ait bir terimdir.",2],
 ["t6","Aşağıdaki cümlelerin hangisinde neden-sonuç ilişkisi vardır?",["Sınavı kazanmak için gece gündüz çalıştı.","Yağmur yağdığı için maç ertelendi.","Erken gelirsen seni de götürürüm.","Sanki bütün dünya onun etrafında dönüyordu."],1,"Maçın ertelenmesinin nedeni yağmurdur. A'da amaç-sonuç, C'de koşul, D'de benzetme vardır.",2],
 ["t6","Aşağıdaki cümlelerin hangisinde amaç-sonuç ilişkisi vardır?",["Hava soğuk olduğundan mont giydim.","Kalabalık yüzünden yürüyemedik.","Kardeşini uyandırmamak için parmak uçlarında yürüdü.","Çok çalıştığından başarılı oldu."],2,"Parmak uçlarında yürüme, kardeşini uyandırmama amacıyla yapılmıştır.",2],
 ["t6","Aşağıdaki cümlelerin hangisi nesnel bir yargı içerir?",["Bu kitap, okuduğum en sürükleyici romandır.","Türkiye'nin en yüksek dağı Ağrı Dağı'dır.","Bu şehrin havası insanı mutlu ediyor.","Yazarın üslubu çok sıkıcı."],1,"Kanıtlanabilir bilgiler nesneldir. Diğerleri kişisel görüşlerdir.",2],
 ["t6","“Sınavı kazandığını duyunca etekleri zil çaldı.” cümlesindeki deyimin anlamı hangisidir?",["Çok korktu.","Çok sevindi.","Çok şaşırdı.","Çok üzüldü."],1,"“Etekleri zil çalmak” çok sevinmek anlamındadır.",2],
 ["t6","Aşağıdaki cümlelerin hangisinde abartma vardır?",["Bu sabah çok erken kalktım.","Seni görmeyeli bin yıl oldu.","Bugün hava biraz serin.","Kitabın yarısını okudum."],1,"Bin yıl, gerçekte mümkün olmayan bir süredir; abartılı anlatımdır.",2],
 ["t6","“Bu yıl da kazanamadı.” cümlesinden aşağıdakilerin hangisi çıkarılabilir?",["İlk kez sınava girmiştir.","Daha önce de kazanamamıştır.","Bu yıl kazanmıştır.","Hiç sınava girmemiştir."],1,"“da” bağlacı daha önce de aynı durumun yaşandığı örtülü anlamını verir.",3],
 ["t6","Aşağıdaki cümlelerin hangisinde koşul anlamı vardır?",["Ders çalıştığı için başarılı oldu.","Hava açarsa pikniğe gideceğiz.","Yorulduğundan erken uyudu.","Kitabı okumak için kütüphaneye gitti."],1,"“Hava açarsa” pikniğe gitmenin koşuludur.",2],
 ["t6","Aşağıdaki cümlelerin hangisinde ikileme farklı anlamda kullanılmıştır?",["Yavaş yavaş yürüyorduk.","Sabah sabah kapıyı çaldı.","Akşamları kitap mitap okumazdı.","Güzel güzel konuşuyorlardı."],2,"“Kitap mitap” ikilemesi “ve benzerleri” anlamı katar; diğerleri pekiştirme ya da durum bildirir.",3],
 ["t6","“Çocukluğumda kurduğum hayallerin yarısını bile gerçekleştiremedim.” cümlesinde aşağıdakilerden hangisi vardır?",["Pişmanlık ya da hayal kırıklığı","Övünme","Tahmin","Öneri"],0,"Gerçekleşmeyen hayallerden duyulan hayal kırıklığı dile getirilmektedir.",2],
 ["t6","Aşağıdaki cümlelerin hangisinde öneri vardır?",["Kitapları okumadan önce yazarın hayatını incelemek gerekir.","Bu kitabı çok beğendim.","Kitap okumayı severim.","Ben her gün kitap okurum."],0,"“-mek gerekir” yapısıyla okura bir yol gösterilmektedir.",2],

 // ---------- Paragrafta Anlam ----------
 ["t7","“Bir kitabı okurken sadece satırları değil, satır aralarını da okumak gerekir. Yazar her şeyi açıkça söylemez; bazı duyguları okuyucunun sezmesini bekler. Bu yüzden iyi bir okuyucu, metindeki suskunlukları da duyabilen kişidir.” Bu paragrafta asıl anlatılmak istenen nedir?",["Yazarlar her şeyi açıkça anlatmalıdır.","İyi bir okuyucu, metnin doğrudan söylemediklerini de sezebilmelidir.","Kitaplar hızlı okunmalıdır.","Satır araları boş bırakılmalıdır."],1,"Paragrafın ana düşüncesi son cümlede verilmiştir: iyi okuyucu metindeki örtük anlamları da kavrar.",2],
 ["t7","“(I) Kapadokya, peribacalarıyla dünyanın sayılı doğal güzelliklerindendir. (II) Bu kayalar, milyonlarca yıl önce yanardağlardan çıkan küllerin rüzgâr ve yağmurla aşınmasıyla oluşmuştur. (III) Bölgede yeraltı şehirleri ve kayalara oyulmuş kiliseler de bulunur. (IV) Karadeniz'in yeşil yaylaları ise yaz aylarında çok kalabalık olur. (V) Sıcak hava balonlarıyla yapılan turlar da bölgeyi ziyaret edenlerin ilgisini çekmektedir.” Bu paragrafta numaralanmış cümlelerden hangisi düşüncenin akışını bozmaktadır?",["II","III","IV","V"],2,"Paragraf Kapadokya'yı anlatmaktadır; IV. cümle Karadeniz'den söz ederek akışı bozar.",2],
 ["t7","“Arılar, bir kilogram bal üretmek için yaklaşık dört milyon çiçeği ziyaret eder. Bir arı kolonisinde ise elli bine yakın arı bulunabilir. Bu küçük canlıların çalışkanlığı, doğadaki dengenin sürmesinde de büyük rol oynar.” Bu paragrafta düşünceyi geliştirmek için daha çok hangi yoldan yararlanılmıştır?",["Tanık gösterme","Karşılaştırma","Sayısal verilerden yararlanma","Benzetme"],2,"Dört milyon çiçek ve elli bin arı gibi sayısal veriler kullanılmıştır.",2],
 ["t7","“Usta bir aşçı ile acemi bir aşçı aynı malzemeleri kullansa da ortaya çıkan yemekler birbirinden çok farklıdır. Yazarlık da böyledir: Aynı sözcükler, yetenekli bir kalemde şiire dönüşürken, yeteneksiz bir kalemde sıradan bir metin olarak kalır.” Bu paragrafta aşağıdakilerden hangisi vurgulanmaktadır?",["Yemek yapmanın yazarlıktan zor olduğu","Bir eserin değerini, malzemeden çok onu kullananın ustalığının belirlediği","Herkesin yazar olabileceği","Aşçıların iyi yazar olduğu"],1,"Benzetme ve karşılaştırma yoluyla ustalığın önemi vurgulanmıştır.",3],
 ["t7","“Teknoloji, hayatımızı kolaylaştıran pek çok yenilik getirdi. ---- Örneğin yan yana oturan insanlar bile birbirleriyle konuşmak yerine ekranlarına bakıyor.” Bu paragrafta boş bırakılan yere düşüncenin akışına göre hangisi getirilmelidir?",["Ancak bu yenilikler insanlar arasındaki yüz yüze iletişimi azalttı.","Bu nedenle herkes teknolojiyi sevmektedir.","Teknoloji her geçen gün ucuzlamaktadır.","Eskiden insanlar mektup yazardı."],0,"“Örneğin” ile başlayan cümle, iletişimin azaldığına örnek vermektedir; boşluğa bu düşünceyi bildiren cümle gelmelidir.",3],
 ["t7","“Yaşlı ağacın dalları rüzgârla hafifçe sallanıyordu. Yaprakların arasından süzülen güneş ışınları, çimenlerin üzerinde altın renkli lekeler oluşturuyordu. Uzaktan bir derenin şırıltısı duyuluyordu.” Bu paragrafta hangi anlatım biçimi kullanılmıştır?",["Tartışmacı anlatım","Betimleyici anlatım","Açıklayıcı anlatım","Öyküleyici anlatım"],1,"Bir manzara, görme ve işitme duyularıyla zihinde canlandırılmıştır: betimleme.",2],
 ["t7","“Bazıları başarının yalnızca yetenekle geldiğini düşünür. Oysa tarihe baktığımızda büyük işler başaran pek çok insanın aslında sıradan yetenekte olduğunu, ancak hiç vazgeçmediğini görürüz. O hâlde başarının asıl anahtarı yetenek değil, sabırdır.” Bu paragrafın anlatım biçimi hangisidir?",["Betimleyici","Öyküleyici","Tartışmacı","Bilgilendirici olmayan açıklayıcı"],2,"Bir görüş verilip (yetenek) karşı çıkılarak başka bir görüş (sabır) savunulmuştur: tartışmacı anlatım.",3],
 ["t7","“Okumak, insanın kendini geliştirmesinin en kolay yoludur. Her kitap, bize başka bir hayatın kapısını aralar. ---- Bu yüzden düzenli kitap okuyan insanlar, olaylara daha geniş bir açıdan bakabilir.” Bu paragrafta boş bırakılan yere hangisi getirilmelidir?",["Kitapların fiyatları her yıl artmaktadır.","Böylece farklı insanların duygu ve düşüncelerini anlamayı öğreniriz.","Ancak okumak çok zaman alır.","Kütüphaneler hafta sonu kapalıdır."],1,"Boşluktan sonraki “bu yüzden” ifadesi, öncesinde farklı bakış açıları kazanmaya dair bir düşünce gerektirir.",2],
 ["t7","“Akıllı telefonlar artık hayatımızın vazgeçilmez bir parçası. Gün içinde bilgiye ulaşmak, iletişim kurmak, alışveriş yapmak için sürekli onları kullanıyoruz. Ancak uzmanlar, özellikle gece yatmadan önce ekrana bakmanın uyku kalitesini düşürdüğünü belirtiyor.” Bu paragrafa göre aşağıdakilerden hangisine ulaşılamaz?",["Akıllı telefonlar birçok amaçla kullanılmaktadır.","Gece ekrana bakmak uykuyu olumsuz etkileyebilir.","Akıllı telefon kullanımı tamamen yasaklanmalıdır.","Uzmanlar ekran kullanımıyla ilgili uyarılarda bulunmaktadır."],2,"Paragrafta yasaklamaya dair bir yargı yoktur; yalnızca gece kullanımına yönelik uyarı vardır.",3],
 ["t7","“Çocukken dedemin bahçesindeki dut ağacına tırmanırdık. Dedem bizi her seferinde uyarır, sonra gülümseyerek en olgun dutları gösterirdi. O ağaç artık yok; ama ne zaman dut görsem dedemin o gülümsemesi aklıma gelir.” Bu paragrafla ilgili hangisi söylenemez?",["Geçmişe özlem duyulmaktadır.","Anlatıcı bir anısını aktarmaktadır.","Öyküleyici anlatımdan yararlanılmıştır.","Bilimsel verilerle bir görüş kanıtlanmaya çalışılmıştır."],3,"Paragrafta bilimsel veri yoktur; kişisel bir anı ve özlem dile getirilmektedir.",2],
 ["t7","“İyi bir dinleyici olmak, iyi bir konuşmacı olmaktan daha zordur. Çünkü konuşurken kendi düşüncelerimizi aktarırız; dinlerken ise kendi düşüncelerimizi bir kenara bırakıp karşımızdakini anlamaya çalışırız. Bu da sabır ve saygı gerektirir.” Bu paragrafın konusu nedir?",["Konuşma sanatının önemi","İyi bir dinleyici olmanın zorluğu","Sabırlı olmanın yararları","Toplum önünde konuşma"],1,"Paragraf, dinlemenin konuşmaktan neden daha zor olduğunu anlatmaktadır.",2],
 ["t7","“(I) Japonya'da depremlere karşı alınan önlemler, dünyaya örnek gösterilmektedir. (II) Binalar, sarsıntıyı esneyerek karşılayacak şekilde inşa edilmektedir. (III) Okullarda her ay deprem tatbikatı yapılmaktadır. (IV) Japon mutfağı da dünyanın en sağlıklı mutfakları arasında sayılır. (V) Bu sayede büyük depremlerde bile can kaybı en aza indirilebilmektedir.” Bu paragrafla ilgili hangisi doğrudur?",["II. cümle düşüncenin akışını bozmaktadır.","IV. cümle çıkarılırsa paragrafın anlam bütünlüğü güçlenir.","V. cümle paragrafın konusu dışındadır.","Paragraf iki paragrafa bölünmelidir ve ikinci paragraf III. cümleyle başlar."],1,"Paragraf deprem önlemlerini anlatmaktadır; IV. cümle mutfaktan söz ederek akışı bozar.",3],

 // ---------- Söz Sanatları ----------
 ["t8","Aşağıdaki cümlelerin hangisinde kişileştirme yapılmıştır?",["Ağaçlar rüzgârla birlikte hüzünlü bir şarkı mırıldanıyordu.","Kar, bütün gece yağdı.","Gökyüzü bulutlarla kaplıydı.","Kuşlar sabah erkenden ötmeye başladı."],0,"Ağaçlara insana özgü “şarkı mırıldanmak” özelliği verilmiştir.",2],
 ["t8","Aşağıdaki cümlelerin hangisinde benzetme vardır?",["Çocuk, aslan gibi güçlü bir sesle bağırdı.","Kapı açık kalmıştı.","Akşam güneş battı.","Dağlar karla kaplanmıştı."],0,"“Aslan gibi” ifadesiyle çocuğun sesi aslanınkine benzetilmiştir.",2],
 ["t8","“Dağ, karşısındaki ovaya seslendi: ‘Senin yeşilliğine imreniyorum.’” Bu cümlede hangi söz sanatları birlikte kullanılmıştır?",["Benzetme ve abartma","Kişileştirme ve konuşturma","Yalnızca abartma","Yalnızca benzetme"],1,"Dağa insan gibi duygu verilmiş (kişileştirme) ve konuşturulmuştur (konuşturma).",3],
 ["t8","Aşağıdaki cümlelerin hangisinde abartma sanatı vardır?",["Gözyaşları sel olup aktı.","Bütün gün ders çalıştı.","Biraz yorgun görünüyordu.","Sabah erkenden yola çıktı."],0,"Gözyaşlarının sel olması gerçekte mümkün olmayan bir abartmadır.",2],
 ["t8","Aşağıdaki dizelerin hangisinde konuşturma sanatı yoktur?",["Bülbül dedi: “Gül olmasa ötmem.”","Karınca söyledi: “Kış gelmeden hazırlan.”","Rüzgâr fısıldadı kulağıma: “Bekle.”","Dağların başında kar var bu sabah."],3,"D'de bir varlığa söz söyletilmemiştir. Diğerlerinde bülbül, karınca ve rüzgâr konuşturulmuştur.",3],
 ["t8","“Şehir, geceleri yorgun bir dev gibi uykuya dalar.” cümlesinde hangi söz sanatları vardır?",["Benzetme ve kişileştirme","Yalnızca konuşturma","Yalnızca abartma","Konuşturma ve abartma"],0,"Şehir deve benzetilmiş (benzetme), ona uykuya dalma ve yorgunluk gibi insana özgü özellikler verilmiştir (kişileştirme).",3],

 // ---------- Metin Türleri ----------
 ["t9","Bir kişinin hayatının, başkası tarafından belgelere dayanılarak anlatıldığı metin türü hangisidir?",["Otobiyografi","Biyografi","Anı","Günlük"],1,"Biyografide hayatı anlatılan kişi ile yazar farklıdır. Otobiyografide kişi kendi hayatını anlatır.",2],
 ["t9","Aşağıdaki metin türlerinden hangisinde yazar, her gün yaşadıklarını tarih atarak yazar?",["Anı","Günlük","Deneme","Fıkra"],1,"Günlük, tarih atılarak günü gününe yazılır. Anıda ise geçmişte yaşanan önemli olaylar sonradan hatırlanarak yazılır.",2],
 ["t9","Bir konuda bilgi vermek veya bir düşünceyi kanıtlamak amacıyla ciddi bir dille, kanıtlara dayanılarak yazılan metin türü hangisidir?",["Deneme","Makale","Sohbet","Öykü"],1,"Makalede düşünce kanıtlanmaya çalışılır. Denemede yazar kişisel görüşlerini kanıtlama kaygısı olmadan samimi bir dille anlatır.",3],
 ["t9","Yazarın herhangi bir konudaki kişisel görüşlerini, kesin yargılara varmadan, kendisiyle konuşur gibi samimi bir dille anlattığı metin türü hangisidir?",["Deneme","Makale","Haber","Biyografi"],0,"Deneme kişiseldir, kanıt kaygısı taşımaz ve samimi bir üslupla yazılır.",3],
 ["t9","Gazete ve dergilerde güncel olayları kısa ve esprili bir dille yorumlayan köşe yazısı türü hangisidir?",["Fıkra","Makale","Anı","Masal"],0,"Fıkra (köşe yazısı) güncel konuları kısa ve akıcı bir dille ele alır.",3],
 ["t9","Gezilip görülen yerlerin, yazarın gözlem ve izlenimleriyle anlatıldığı metin türü hangisidir?",["Gezi yazısı","Günlük","Mektup","Masal"],0,"Gezi yazısı, gezilen yerlerin tarihî, kültürel ve doğal özelliklerini anlatır.",2],
 ["t9","Bir yazarın, okuyucuyla karşılıklı konuşuyormuş gibi samimi bir dille ve kesin kanıtlara başvurmadan yazdığı metin türü hangisidir?",["Sohbet (söyleşi)","Makale","Haber","Eleştiri"],0,"Sohbette yazar okuyucuyla konuşur gibi yazar; “değil mi?”, “siz ne dersiniz?” gibi ifadeler sıkça kullanılır.",3],

 // ---------- Anlatım Bozuklukları ----------
 ["t10","Aşağıdaki cümlelerin hangisinde gereksiz sözcük kullanımından kaynaklanan bir anlatım bozukluğu vardır?",["Yarın sabah erkenden yola çıkacağız.","Bu konuyu tekrar yeniden gözden geçirelim.","Kitabı okuyup bitirdim.","Akşam yemeğinden sonra yürüyüşe çıktık."],1,"“Tekrar” ve “yeniden” aynı anlamdadır; biri gereksizdir.",2],
 ["t10","Aşağıdaki cümlelerin hangisinde anlamca çelişen sözcükler bir arada kullanılmıştır?",["Kesinlikle yarın gelirim.","Galiba kesinlikle haklısın.","Belki yarın gelirim.","Herhalde bugün yağmur yağar."],1,"“Galiba” tahmin, “kesinlikle” kesinlik bildirir; birlikte kullanılamaz.",2],
 ["t10","“Yaz tatilinde tahminen tam on gün kaldık.” cümlesindeki anlatım bozukluğunun nedeni hangisidir?",["Gereksiz sözcük kullanımı","Anlamca çelişen sözcüklerin bir arada kullanılması","Özne-yüklem uyumsuzluğu","Ek eksikliği"],1,"“Tahminen” ile “tam” çelişir; biri belirsizlik, diğeri kesinlik bildirir.",3],
 ["t10","Aşağıdaki cümlelerin hangisinde mantık hatasından kaynaklanan bir anlatım bozukluğu vardır?",["Bu yıl kışın çok kar yağdı.","Sınavdan çok kötü bir not aldığı için mutlu oldu.","Etkin ders çalışma yöntemleri başarıyı artırır.","Yolun sonunda bizi güzel bir manzara bekliyordu."],1,"Kötü not almak mutlu olmanın nedeni olamaz; neden-sonuç ilişkisi mantığa aykırı kurulmuştur.",3],
 ["t10","Aşağıdaki cümlelerin hangisinde bağlacın yanlış kullanılmasından kaynaklanan bir anlatım bozukluğu vardır?",["Hem okula hem de kursa düzenli gidiyor.","Bu olaydan sonra ne arkadaşlarına ne de ailesine güvenmiyordu.","Ya bugün gel ya da yarın.","Kitabı okudu ama hiç beğenmedi."],1,"“ne… ne” bağlacı cümleye olumsuzluk anlamı katar; yüklemin de olumsuz olması anlatımı bozar. Doğrusu: “ne arkadaşlarına ne de ailesine güveniyordu.”",3],
 ["t10","“Bu sorunu çözmek ve ilgilenmek için bir komisyon kuruldu.” cümlesindeki anlatım bozukluğunun nedeni hangisidir?",["Gereksiz sözcük kullanımı","Tümleç eksikliği (ilgilenmek eylemi “-e/-le” tümleci istediği hâlde “sorunu” ögesine bağlanmıştır)","Özne-yüklem uyumsuzluğu","Anlamca çelişen sözcüklerin kullanımı"],1,"“Sorunu çözmek” uygundur ama “sorunu ilgilenmek” söylenemez; “bu sorunla ilgilenmek” denmeliydi.",3],
 ["t10","Aşağıdaki cümlelerin hangisinde özne-yüklem uyumsuzluğu vardır?",["Biz bu yaz köye gideceğiz.","Ben ve arkadaşlarım her gün parka gideriz.","Sen ve ben bu işi birlikte başaracaksın.","Çocuklar bahçede oynuyor."],2,"“Sen ve ben” öznesi birinci çoğul kişiyi (biz) gerektirir; yüklem “başaracağız” olmalıdır.",3],

 // ---------- Sözel Mantık ve Görsel Okuma ----------
 ["t11","D, B, C, A ve E adlı beş öğrenci yan yana dizilmiş beş sandalyeye (soldan sağa 1–5) oturmuştur. Bilinenler:\n• C tam ortada oturmaktadır.\n• A, E'nin hemen solundadır.\n• D uçlardan birinde oturmaktadır.\n• B, D'nin sağında oturmaktadır.\nBuna göre B kaçıncı sandalyededir?",["1","2","4","5"],1,"C = 3. B, D'nin sağında olduğundan D en sağda olamaz; D = 1. A-E ikilisi yalnızca 4-5'e sığar. Geriye kalan 2. sandalye B'nindir: D, B, C, A, E.",3],
 ["t11","Elif, Fatma ve Gül; resim, müzik ve satranç kurslarına pazartesi, çarşamba ve cuma günleri gitmektedir. Her biri farklı bir kursa, farklı bir günde gider. Bilinenler:\n• Elif satranç kursuna gitmez ve pazartesi günü kursa gitmez.\n• Müzik kursu cuma günüdür.\n• Gül resim kursuna gider.\n• Fatma çarşamba günü kursa gider.\nBuna göre Gül hangi gün kursa gitmektedir?",["Pazartesi","Çarşamba","Cuma","Kesin olarak belirlenemez."],0,"Gül resim; Elif satranç değil, o hâlde müzik → cuma. Fatma satranç → çarşamba. Gül'e pazartesi kalır.",3],
 ["t11","Bir okulda 100 öğrenciye en sevdikleri spor sorulmuş; sonuçlar şöyledir: Futbol 40, Voleybol 25, Basketbol 20, Yüzme 15. Bu verilere göre aşağıdakilerden hangisi söylenemez?",["Futbolu seçenlerin sayısı voleybol ve yüzmeyi seçenlerin toplamına eşittir.","Basketbolu seçenler yüzmeyi seçenlerden fazladır.","Öğrencilerin yarısından fazlası futbolu seçmiştir.","Voleybol ve basketbolu seçenlerin toplamı futbolu seçenlerden fazladır."],2,"Futbolu seçenler 100 öğrencinin 40'ıdır, yani yarısından azdır.",3],
 ["t11","Kerem, Lale, Mert ve Nur bir sınavda farklı puanlar almıştır. Bilinenler:\n• Lale'nin puanı Mert'ten yüksektir.\n• Nur en yüksek puanı almamıştır ama Lale'den yüksek puan almıştır.\n• Kerem, Mert'ten yüksek puan almıştır.\nBuna göre puanların yüksekten düşüğe sıralanışı hangisidir?",["Kerem, Nur, Lale, Mert","Nur, Kerem, Lale, Mert","Kerem, Lale, Nur, Mert","Kerem, Nur, Mert, Lale"],0,"Nur > Lale > Mert. Nur en yüksek puanı almadığına göre ondan yüksek tek kişi Kerem olabilir: Kerem > Nur > Lale > Mert.",3],
 // ---------- Paragrafta Anlam (ek) ----------
 ["t7","“Çocukken bisiklete binmeyi öğrenirken kaç kez düştüğümüzü kimse saymazdı. Düşmek, o günlerde öğrenmenin doğal bir parçasıydı. Büyüdükçe hata yapmaktan öyle korkar olduk ki yeni bir işe başlamayı bile erteliyoruz. Oysa hatayı bir utanç değil, bir basamak olarak görebilsek öğrenmek yeniden kolaylaşacak.” Bu paragrafın ana düşüncesi aşağıdakilerden hangisidir?",["Çocuklar yetişkinlerden daha hızlı öğrenir.","Hata yapmaktan korkmamak öğrenmeyi kolaylaştırır.","Bisiklete binmek kolay öğrenilen bir beceridir.","Yetişkinler yeni işlere başlamadan önce iyice düşünmelidir."],1,"Paragraf, hatayı bir basamak olarak görmenin öğrenmeyi kolaylaştıracağı yargısıyla biter; ana düşünce budur. Bisiklet örneği yalnızca düşünceyi desteklemek için kullanılmıştır.",3],
 ["t7","“Mahallemizdeki halk kütüphanesi artık yalnızca kitap ödünç alınan bir yer değil. Hafta sonları çocuklar için masal saatleri düzenleniyor, yaşlılar için bilgisayar kursları açılıyor. Salonlardan biri de sessizce ders çalışmak isteyen öğrencilere ayrılmış. Kütüphane böylece mahallenin her yaştan insanını bir araya getiren bir buluşma noktasına dönüşmüş.” Bu paragrafta aşağıdakilerden hangisine değinilmemiştir?",["Çocuklara yönelik etkinliklere","Yaşlılara verilen kurslara","Öğrencilere ayrılan çalışma alanına","Kütüphanenin açılış ve kapanış saatlerine"],3,"Paragrafta masal saatleri, bilgisayar kursları ve çalışma salonundan söz edilir; çalışma saatlerine değinilmez.",2],
 ["t7","“(I) Zeytin ağacı yüzlerce yıl yaşayabilen, dayanıklı bir bitkidir. (II) Kurak topraklarda bile kök salabilmesi, onu Akdeniz ikliminin simgesi yapmıştır. (III) Bazı zeytin ağaçlarının bin yaşını aştığı bilinmektedir. (IV) Zeytinyağı ise sağlıklı beslenmenin vazgeçilmezleri arasında gösterilir. (V) İçerdiği yağ asitleri kalp sağlığını destekler, pek çok yemeğin de lezzetini artırır.” Bu metin iki paragrafa ayrılmak istense ikinci paragraf hangi cümleyle başlar?",["II","III","IV","V"],2,"I–III. cümleler zeytin ağacını, IV. ve V. cümleler zeytinyağını anlatır. Konu IV. cümlede değişir; “ise” bağlacı da bu geçişi gösterir.",3],
 ["t7","“Bildirim sesleri, kısa videolar ve sürekli yenilenen sayfalar dikkatimizi saniyeler içinde bir yerden başka bir yere taşıyor. Bir kitabı yarım saat kesintisiz okuyabilmek bile artık pek çok kişi için zor. Dikkat, tıpkı bir kas gibi kullanılmadıkça zayıflıyor.” Bu paragraf aşağıdaki cümlelerden hangisiyle sürdürülürse anlam bütünlüğü korunur?",["Bu yüzden odaklanma becerisini korumak için ekran süremizi bilinçli olarak sınırlamalıyız.","Kitaplar eskiden bugünkünden çok daha pahalıydı.","Telefonların ekranları her yıl biraz daha büyüyor.","Kısa videolar insanlara eğlenceli vakit geçirme imkânı sunar."],0,"Paragraf dikkatin dağılmasını ve zayıflamasını anlatmaktadır; buna önlem öneren A seçeneği akışı sürdürür. D seçeneği konuyla ilgili görünse de paragrafın eleştirel yönünü tersine çevirir.",3],
 ["t7","“Şehirde sabahlar trafik gürültüsüyle başlarken köyde horoz sesiyle başlar. Şehirli, her şeye yetişmeye çalışırken köylü işini güneşin doğuşuna ve batışına göre düzenler. Şehirde komşular birbirini çoğu zaman tanımaz, köyde ise herkes birbirinin derdine ortaktır.” Bu paragrafta düşünceyi geliştirmek için daha çok hangi yoldan yararlanılmıştır?",["Tanımlama","Karşılaştırma","Örnekleme","Sayısal verilerden yararlanma"],1,"Şehir ve köy hayatı benzerlik ve farklılıklarıyla karşı karşıya konmuştur; bu, karşılaştırmadır.",2],
 ["t7","“Pencerenin önündeki yaşlı çınarın dalları, rüzgâr estikçe camlara hafifçe vuruyordu. Yaprakların arasından süzülen ışık, odanın tahta zeminine altın rengi lekeler bırakıyordu. Masadaki çay bardağından ince bir buhar yükseliyor, duvardaki saatin tıkırtısı sessizliği bölüyordu.” Bu paragrafın anlatım biçimi aşağıdakilerden hangisidir?",["Öyküleme","Tartışma","Betimleme","Açıklama"],2,"Paragrafta bir olay anlatılmıyor; oda, ışık, ses gibi ayrıntılarla bir ortamın görüntüsü çiziliyor. Bu betimlemedir.",2],
 ["t7","“Arıların azalması sanıldığından çok daha büyük bir sorundur. ______ Bu nedenle arıların yok olması, sofralarımızdaki pek çok yiyeceğin de azalması anlamına gelir. Tarım ilaçlarının bilinçsiz kullanımı ise bu tehlikeyi her geçen gün büyütmektedir.” Bu paragrafta boş bırakılan yere aşağıdakilerden hangisi getirilmelidir?",["Arılar kovanlarında sıkı bir iş bölümüyle yaşar.","Çünkü yediğimiz meyve ve sebzelerin önemli bir kısmı arıların taşıdığı polenlerle tozlaşır.","Bal, yüzyıllardır şifa kaynağı olarak kullanılmaktadır.","Bazı arı türleri insanlara karşı saldırgan olabilir."],1,"Boşluktan sonraki cümle “Bu nedenle” diye başlayıp arıların yok olmasını yiyeceklerin azalmasına bağlıyor; boşlukta bu sonucun nedeni olmalıdır.",3],
 ["t7","“Yazar, ilk romanını yazarken her bölümü en az beş kez baştan yazmış. Taslaklardan birini okuyan editörü bu hâliyle de basılabileceğini söylediğinde bile durmamış; bir cümlenin yerini değiştirmek için günlerce düşündüğü olmuş. Roman yayımlandığında eleştirmenler, kitabın en güçlü yanının dilindeki sadelik olduğunu yazmışlar.” Bu paragraftan aşağıdakilerden hangisi çıkarılamaz?",["Yazar eserini titizlikle işlemiştir.","Romanın dili eleştirmenlerce beğenilmiştir.","Editör, taslaklardan birini yayımlanabilecek düzeyde bulmuştur.","Roman, yayımlandığı yıl en çok satan kitaplar arasına girmiştir."],3,"Paragrafta satış rakamlarına dair hiçbir bilgi yoktur. Diğer yargılar metinde açıkça ya da dolaylı olarak yer alır.",3],
 ["t7","“Ergenlik döneminde vücut, özellikle gece uykusunda salgılanan hormonlarla hızla büyür ve gelişir. Gün içinde öğrenilen bilgiler de uyku sırasında beyinde düzenlenerek kalıcı hâle gelir. Bu yüzden sınav öncesinde uykusundan feda ederek ders çalışan bir öğrenci, aslında öğrendiklerinin bir kısmını kaybetme riskini göze almış olur.” Bu paragrafın konusu aşağıdakilerden hangisidir?",["Sınava hazırlanma yöntemleri","Uykunun büyüme ve öğrenmedeki önemi","Ergenlik döneminin sorunları","Hormonların vücuttaki görevleri"],1,"Paragrafın her cümlesi uykunun büyümeye ve öğrenmeye katkısını işler. Sınav, hormon ve ergenlik bu konunun ayrıntılarıdır.",2],
 ["t7","“Eskiden bir şehri tanımanın yolu, sokaklarında kaybolmaktı. Haritaya bakmadan yürür, bir köşeyi döndüğünde karşına çıkan küçük bir kahveyi, eski bir çeşmeyi kendin keşfederdin. Bugün telefonlarımız bizi en kısa yoldan hedefe ulaştırıyor; ama en kısa yol, çoğu zaman en az şey gördüğümüz yol oluyor.” Bu paragrafta yazar asıl olarak neyi vurgulamaktadır?",["Telefonların yol bulmada hata yapabileceğini","Teknolojinin, şehri keşfetme deneyimini azalttığını","Eski şehirlerin bugünkülerden daha güzel olduğunu","Kahve ve çeşmelerin şehrin simgeleri olduğunu"],1,"Son cümle, en kısa yolu gösteren teknolojinin keşfetme ve görme fırsatını azalttığını vurgular. C seçeneği metinde yer almayan bir karşılaştırmadır.",3],

 // ---------- Paragrafta Anlam (ek 2) ----------
 ["t7","“Bir şehrin gerçek yüzünü görmek isteyen, rehberlerin önerdiği meydanlarda değil, sabahın erken saatlerinde açılan fırınların önünde durmalı. Simitçinin tezgâhını kurduğu, esnafın kepenk kaldırdığı, okula yetişmeye çalışan çocukların koşturduğu o saatlerde şehir henüz kimse için süslenmemiştir. Kartpostallardaki şehir bir vitrindir; asıl şehir, o vitrinin arkasındaki gündelik hayattadır.” Bu paragrafın ana düşüncesi aşağıdakilerden hangisidir?",["Turistik yerler gezilmeye değmez.","Bir şehri tanımak için onun gündelik hayatına bakmak gerekir.","Sabahın erken saatleri şehrin en kalabalık zamanıdır.","Kartpostallar şehirleri olduğundan güzel gösterir."],1,"Paragraf, şehrin asıl yüzünün gündelik hayatta görüleceği yargısıyla biter. A seçeneği metindekinden çok daha kesin bir yargıdır; turistik yerlerin değersiz olduğu söylenmemiştir.",3],
 ["t7","“Ödev, sınıfta öğrenileni pekiştirmenin bir yolu olabilir; ama bir çocuğun bütün akşamını kaplıyorsa amacından sapmış demektir. Kitap okumaya, oyun oynamaya, ailesiyle sohbet etmeye vakit bulamayan bir öğrenci, ödevlerini eksiksiz yapsa bile öğrenmenin tadını kaçırır. Bence ödevin değeri, miktarında değil, öğrenciyi düşünmeye yöneltip yöneltmemesindedir.” Bu paragrafta yazarın ödevle ilgili savunduğu görüş aşağıdakilerden hangisidir?",["Ödevler tamamen kaldırılmalıdır.","Ödevin niteliği, miktarından daha önemlidir.","Ödevler aileyle birlikte yapılmalıdır.","Ödevler yalnızca hafta sonları verilmelidir."],1,"Yazar ödevin pekiştirmeye yarayabileceğini kabul eder, karşı çıktığı şey aşırı miktardır; son cümlede değerin miktarda değil düşündürmede olduğunu söyler. A seçeneği ilk cümleyle çelişir.",3],
 ["t7","1. metin: “Fotoğraf, bir anı dondurarak unutulmaktan kurtarır. Yıllar sonra eski bir fotoğrafa baktığımızda yalnızca bir görüntüyü değil, o günün sesini ve kokusunu da hatırlarız.”\n2. metin: “Bugün her şeyi fotoğraflıyoruz: yediğimiz yemeği, yürüdüğümüz yolu, gördüğümüz her manzarayı. Ekrandan bakmaktan anı yaşamayı unutuyoruz; çektiğimiz binlerce fotoğrafın çoğuna da bir daha hiç bakmıyoruz.”\nBu iki metinle ilgili aşağıdakilerden hangisi söylenebilir?",["İki metinde de fotoğraf çekmenin gereksiz olduğu savunulmuştur.","1. metinde fotoğrafın hatırlamaya katkısı, 2. metinde ise fotoğraf çekme alışkanlığının anı yaşamaya engel olabileceği vurgulanmıştır.","1. metinde fotoğraf makinelerinin gelişimi anlatılmıştır.","2. metinde eski fotoğrafların değeri öne çıkarılmıştır."],1,"1. metin fotoğrafı olumlu bir hatırlama aracı olarak ele alır; 2. metin aşırı fotoğraf çekmenin anı yaşamayı engellediğini söyler. A seçeneği 1. metinle çelişir.",3],
 ["t7","“Annem yıllardır aynı terziye gider. Terzinin dükkânı küçücüktür; ışığı az, rafları dağınıktır. Ama annem şehrin en büyük mağazalarını gezdikten sonra bile dönüp ona gelir. Terzi, kumaşa makas vurmadan önce müşterisiyle uzun uzun konuşur; elbisenin nerede giyileceğini, nasıl hissettirmesi gerektiğini sorar.” Bu paragraftan aşağıdakilerden hangisine ulaşılabilir?",["Terzi, işini yaparken müşterisinin isteklerini önemser.","Terzinin dükkânı şehrin en kalabalık yerindedir.","Anne, büyük mağazalardan hiç alışveriş yapmamıştır.","Terzi, diğer terzilerden daha ucuz çalışır."],0,"Terzinin dikmeden önce müşteriyle uzun uzun konuşması bu yargıyı destekler. Annenin mağazaları gezdiği söylenir ama hiç alışveriş yapmadığı çıkarılamaz; konum ve fiyat bilgisi metinde yoktur.",3],
 ["t7","“Bir ağaç dikmek, sonucu hemen görülmeyen işlerin en güzel örneklerinden biridir. Fidanı toprağa koyan kişi, çoğu zaman onun gölgesinde oturacak kadar uzun yaşamayacağını bilir. ______” Bu paragraf aşağıdakilerden hangisiyle tamamlanırsa anlam bütünlüğü sağlanır?",["Fidanlar ilkbaharda dikildiğinde daha kolay kök salar.","Bu yüzden insanlar artık ağaç dikmek yerine hazır bahçeler satın alıyor.","Yine de dikmekten vazgeçmez; çünkü asıl amaç, kendinden sonra gelenlere bir şey bırakmaktır.","Ağaçların yaşı, gövdelerindeki halkalar sayılarak bulunabilir."],2,"Paragraf, sonucunu göremeyeceği hâlde ağaç diken kişiyi anlatmaktadır; C seçeneği bu durumun nedenini vererek düşünceyi tamamlar. A ve D konudan sapar, B ise paragrafın övgü dolu bakışıyla çelişir.",2],
 ["t7","“(I) Kelebekler, renkli kanatlarıyla doğanın en dikkat çekici canlıları arasındadır. (II) Kanatlardaki renkler, üst üste dizilmiş binlerce minik pulun ışığı yansıtmasıyla oluşur. (III) Bu pullar dokunulduğunda kolayca dökülür ve kanat zarar görebilir. (IV) Arılar ise topladıkları nektarı kovanlarında bala dönüştürür. (V) Bu yüzden kelebekleri elle tutmaktan kaçınmak gerekir.” Bu paragrafta numaralanmış cümlelerden hangisi düşüncenin akışını bozmaktadır?",["II","III","IV","V"],2,"Paragraf kelebek kanatlarını ve onlara dokunmanın zararını anlatır. IV. cümle arılardan söz ederek akışı keser; V. cümledeki “Bu yüzden” de III. cümleye bağlanır.",2],
 ["t7","“Empati, kendini başkasının yerine koyarak onun duygu ve düşüncelerini anlamaya çalışmaktır. Örneğin sınavdan düşük not alan bir arkadaşımıza ‘Boş ver, önemli değil.’ demek yerine onun hayal kırıklığını anlamaya çalışmak empatik bir davranıştır. Empati kuramayan biri ise haritası olmayan bir yolcu gibi, başkalarının iç dünyasında yolunu kaybeder.” Bu paragrafta düşünceyi geliştirme yollarından hangisine başvurulmamıştır?",["Tanımlama","Örnekleme","Benzetme","Sayısal verilerden yararlanma"],3,"İlk cümle tanım, ikinci cümle örnek (“Örneğin”), üçüncü cümle benzetmedir (“haritası olmayan bir yolcu gibi”). Paragrafta hiçbir sayısal veri yoktur.",3],
 ["t7","“Deniz kaplumbağaları yumurtalarını kumsallara bırakır. Yavrular genellikle gece yumurtadan çıkar ve denizin üzerindeki parıltıya doğru ilerleyerek suya ulaşır. Ancak kıyıdaki otel ve restoranların ışıkları yavruları denize değil karaya doğru yönlendirir; pek çoğu denize hiç ulaşamaz. Bu nedenle kaplumbağaların yumurtladığı kumsallarda gece aydınlatmasının sınırlanması büyük önem taşır.” Bu paragrafa en uygun başlık aşağıdakilerden hangisidir?",["Kaplumbağalar Nasıl Beslenir?","Işıklar Yavruların Yolunu Şaşırtıyor","Denizlerin En Hızlı Canlıları","Turizmin Ekonomiye Katkıları"],1,"Paragrafın özü, yapay ışıkların yavruları denize ulaşmaktan alıkoymasıdır. Diğer başlıklar metinde işlenmeyen konulara aittir.",2],
 ["t7","“Bazı insanlar başarıyı yalnızca varılan sonuçla ölçer. Oysa bir dağa tırmananın asıl kazancı, zirvedeki manzaradan çok yol boyunca kazandığı dayanıklılıktır. Zirveye ulaşamayan bir dağcı bile ilk denemesine göre daha güçlü ve daha deneyimli olarak iner. Bu açıdan bakıldığında başarı bir ______ değil, bir süreçtir.” Bu paragrafta boş bırakılan yere aşağıdakilerden hangisi getirilmelidir?",["yolculuk","varış noktası","deneyim","çaba"],1,"Paragraf, başarının yalnızca sonuçla ölçülmesine karşı çıkar; boşluğa “sonuç” anlamındaki “varış noktası” gelmelidir. “Yolculuk”, “deneyim” ve “çaba” sürecin parçalarıdır; “süreç değil” yapısıyla çelişir.",2],
 ["t7","Aşağıdaki cümlelerden hangisi bir paragrafın giriş cümlesi olmaya en uygundur?",["Bu nedenle sözlükler her yıl yeni kelimelerle güncellenir.","Her dilin, onu konuşan toplumun yaşayışını yansıtan kendine özgü bir söz varlığı vardır.","Ayrıca bu sözlerin çoğu başka dillere birebir çevrilemez.","Onun da bu konuda söyledikleri dikkat çekicidir."],1,"Giriş cümlesi kendinden önce bir cümleye ihtiyaç duymaz ve genel bir yargı bildirir. “Bu nedenle”, “Ayrıca” ve “Onun da” ifadeleri önceki bir cümleye bağlanmayı gerektirir.",2],
 ["t7","“(I) Yeni açılan kütüphane, şehrin merkezinde üç katlı bir binada hizmet veriyor. (II) Kütüphanede çocuklar için ayrılmış bir okuma salonu bulunuyor. (III) Binanın en güzel yeri ise geniş pencereleriyle şehre bakan çatı katı. (IV) Kütüphane hafta içi her gün 09.00 ile 21.00 arasında açık.” Bu paragraftaki numaralanmış cümlelerden hangisi kişisel görüş (öznel yargı) içermektedir?",["I","II","III","IV"],2,"“En güzel yeri” değerlendirmesi kişiden kişiye değişir; III. cümle özneldir. Diğerleri doğruluğu kontrol edilebilecek bilgiler verir.",2],
 ["t7","“Mahalle aralarındaki boş arsalar eskiden çocukların futbol, saklambaç oynadığı yerlerdi. Şimdi o arsaların her birinde yeni bir apartman yükseliyor. Çocuklar ya bilgisayar başında ya da kapalı spor salonlarındaki ücretli kurslarda. Sokakta, kurallarını kendi koyduğu oyunları oynayan çocuk artık neredeyse görülmüyor.” Bu paragrafta asıl yakınılan durum aşağıdakilerden hangisidir?",["Spor kurslarının pahalı olması","Çocukların sokakta özgürce oynayabileceği alanların ve oyunların azalması","Apartmanların çok katlı yapılması","Çocukların futbolu sevmemesi"],1,"Paragrafın her cümlesi sokak oyunlarının ve oyun alanlarının kaybolmasına bağlanır. Kursların ücretli olması ve apartmanlar bu kaybın ayrıntılarıdır; futbolu sevmeme metinde yoktur.",3],
 ["t7","“Dedem, tamir edemeyeceği bir şey olmadığına inanırdı. Bozulan radyoyu, sallanan sandalyeyi, kapanmayan pencereyi hiç üşenmeden elden geçirirdi. Bir şeyi atmadan önce mutlaka ‘Bir bakalım hele.’ derdi. Çoğu zaman da gerçekten onarır, onardığı eşyayı yeni almış gibi sevinçle kullanırdı.” Bu paragrafta dedenin hangi özelliğinden söz edilmemiştir?",["Becerikli olmasından","Üşengeç olmamasından","Eşyalarına değer vermesinden","Çevresindekilere karşı cömert olmasından"],3,"Onarabilmesi beceriyi, “hiç üşenmeden” ifadesi çalışkanlığı, eşyayı atmadan önce onarmaya çalışması eşyaya verdiği değeri gösterir. Cömertliğiyle ilgili bir bilgi yoktur.",2],
 ["t7","Aşağıdaki numaralanmış cümlelerle anlamlı bir paragraf oluşturulduğunda baştan üçüncü cümle hangisi olur?\nI. Ardından toprağı havalandırmak için iyice beller.\nII. Bahçıvan, sebze ekmeden önce toprağı taşlardan ve yabani otlardan temizler.\nIII. En son tohumları eker ve toprağı bolca sular.\nIV. Bellenmiş toprağa, bitkilerin gelişmesine yardımcı olacak gübreyi karıştırır.",["I","II","III","IV"],3,"Doğru sıra II – I – IV – III'tür: önce temizlik, “Ardından” bellemek, “Bellenmiş toprağa” gübre, “En son” ekim. Üçüncü cümle IV'tür.",3],
 ["t7","“Ebru, su üzerinde oluşturulan desenlerin kâğıda aktarılmasıyla yapılan bir sanattır. Kitreyle koyulaştırılmış su bir tekneye konur, yüzeyine fırçayla boyalar serpilir ve bu boyalar bizle şekillendirilir. Ardından tekneye yatırılan kâğıt, sudaki deseni üzerine alır. Her ebru tektir; çünkü sudaki boya hareketleri hiçbir zaman aynı biçimde tekrarlanamaz.” Bu paragrafta aşağıdaki sorulardan hangisinin cevabı yoktur?",["Ebru nedir?","Ebru nasıl yapılır?","Her ebru neden birbirinden farklıdır?","Ebru sanatı ilk kez nerede ortaya çıkmıştır?"],3,"Paragraf ebruyu tanımlar, yapılışını anlatır ve her ebrunun neden tek olduğunu açıklar. Sanatın nerede doğduğuna dair bilgi yoktur.",2],
 ["t7","“Bir dili öğrenmek, kelimelerin karşılıklarını ezberlemekten ibaret değildir. ‘Kolay gelsin’ sözünü başka bir dile kelimesi kelimesine çevirdiğinizde çoğu zaman tuhaf bir cümle ortaya çıkar; çünkü bu söz, çalışana duyulan saygıyı dile getiren bir alışkanlıktan doğmuştur. Dil, onu konuşan toplumun yaşayışını ve değerlerini de taşır. Bu yüzden bir dili gerçekten öğrenmek, biraz da o dili konuşanları tanımaktır.” Bu paragrafta vurgulanan düşünce aşağıdakilerden hangisidir?",["Türkçe, öğrenilmesi en zor dillerden biridir.","Bir dili öğrenmek, o dili konuşan toplumun kültürünü tanımayı da gerektirir.","Kelime ezberlemek dil öğrenmenin en etkili yoludur.","Çeviri yapmak her zaman yanlış sonuç verir."],1,"Son cümle bu yargıyı açıkça verir. C seçeneği ilk cümleyle çelişir; D seçeneği “her zaman” diyerek metnin söylemediği bir genelleme yapar.",3],
 ["t7","“Bir konser salonunda alkışlar hep sahnedeki müzisyenler içindir. Oysa o gece kusursuz geçsin diye salonun sesini ayarlayan teknisyenler, ışıkları yöneten görevliler, sabaha kadar sahneyi kuran işçiler de vardır. Hiçbiri sahneye çıkıp selam vermez; ama onların görünmez emeği olmadan o alkışların hiçbiri kopmazdı.” Bu paragrafta “görünmez emek” sözüyle anlatılmak istenen aşağıdakilerden hangisidir?",["Müzisyenlerin konserlere yeterince hazırlanmaması","Bir başarının ardında, adı duyulmayan kişilerin katkılarının bulunması","Teknisyenlerin işinin müzisyenlerinkinden zor olması","Konser salonlarında az sayıda personel çalışması"],1,"Söz, alkışlanmayan ama başarıya katkıda bulunan kişilerin emeğini anlatır. Metinde müzisyenlerin hazırlıksızlığı ya da iki işin zorluğunun karşılaştırılması yoktur.",3],
 // ---------- Sözel Mantık (ek) ----------
 ["t11","Ada, Bera, Can, Duru ve Ege yan yana dizilmiş beş sandalyeye (soldan sağa 1–5) oturmuştur. Bilinenler:\n• Ege 1 numaralı sandalyededir.\n• Ada uçlardaki sandalyelerden birinde oturmamaktadır.\n• Can, Duru'nun hemen sağında oturmaktadır.\n• Bera ile Ege yan yana değildir.\n• Bera, Can'ın solunda oturmaktadır.\n• Ada ile Duru yan yana değildir.\nBuna göre 4 numaralı sandalyede kim oturmaktadır?",["Ada","Bera","Can","Duru"],3,"Ege 1. Bera 2'de olamaz. Duru–Can ikilisi ve Ada'nın yeri denendiğinde tek uygun düzen: Ege, Ada, Bera, Duru, Can. 4 numarada Duru oturur.",3],
 ["t11","Ada, Bera, Can, Duru ve Ege yan yana dizilmiş beş sandalyeye (soldan sağa 1–5) oturmuştur. Bilinenler:\n• Ege 1 numaralı sandalyededir.\n• Ada uçlardaki sandalyelerden birinde oturmamaktadır.\n• Can, Duru'nun hemen sağında oturmaktadır.\n• Bera ile Ege yan yana değildir.\nBuna göre aşağıdakilerden hangisi kesinlikle doğrudur?",["Bera 5 numaralı sandalyede oturur.","Ada 2 numaralı sandalyede oturur.","Duru en sağdaki sandalyede oturmaz.","Can, Bera'nın solunda oturur."],2,"Üç farklı düzen mümkündür (E-A-B-D-C, E-A-D-C-B, E-D-C-A-B). Can, Duru'nun hemen sağında olduğundan Duru hiçbir düzende 5. sandalyede olamaz; diğer seçenekler her düzende doğru değildir.",3],
 ["t11","Bir okuldaki satranç, müzik, resim, spor ve drama kulüpleri pazartesiden cumaya kadar her gün bir kulüp olacak biçimde toplanmaktadır. Bilinenler:\n• Satranç kulübü salı günü toplanır.\n• Drama kulübü, satranç kulübünden hemen sonraki gün toplanır.\n• Spor kulübü haftanın ilk ya da son günü toplanır.\n• Müzik kulübü resim kulübünden önce toplanır.\n• Resim kulübü cuma günü toplanmaz.\nBuna göre perşembe günü hangi kulüp toplanır?",["Müzik","Resim","Spor","Drama"],1,"Salı satranç, çarşamba drama. Pazartesi, perşembe ve cuma; müzik, resim ve spora kalır. Resim cuma olamaz, müzik resimden önce olmalı: pazartesi müzik, perşembe resim, cuma spor.",3],
 ["t11","Ali, Banu ve Cem'den biri vazoyu kırmıştır. Üçünün söyledikleri şunlardır:\n• Ali: “Ben kırmadım.”\n• Banu: “Vazoyu Cem kırdı.”\n• Cem: “Banu yalan söylüyor.”\nBu üç kişiden yalnızca birinin doğru söylediği bilindiğine göre vazoyu kim kırmıştır?",["Ali","Banu","Cem","Kesin olarak belirlenemez."],0,"Vazoyu Ali kırdıysa: Ali yalan, Banu yalan, Cem doğru → yalnız bir doğru. Banu kırdıysa Ali ve Cem doğru olur; Cem kırdıysa Ali ve Banu doğru olur. Tek uygun durum Ali'dir.",3],
 ["t11","30 kişilik bir sınıfta 18 öğrenci satranç kursuna, 14 öğrenci yüzme kursuna gitmektedir. Bu iki kursa da gitmeyen 5 öğrenci olduğuna göre her iki kursa birden giden kaç öğrenci vardır?",["5","7","9","11"],1,"En az bir kursa giden 30 − 5 = 25 öğrenci. 18 + 14 − x = 25 → x = 7.",3]
]);
